	protected APUSubscriber subscriber = null;
	private final String unexpectedErrorMsg = ":::::::::::::: Unexpected Error :::::::::::::::::";
	private final Logger LOGGER = Logger.getLogger(APUTest.class.getName());
	private String testingStep = "";
	private Integer sizeOfAPUList = 0;
